import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate, Link, useLocation } from 'react-router-dom';
import { useAuth } from '../hooks/AuthContext';
import { fetchResume, createResume, updateResume } from '../services/resumeService';
import ResumePreview from '../components/ResumePreview';
import './ResumeBuilder.css';

const EMPTY = {
  personalInfo: {
    name: '',
    title: '',
    email: '',
    phone: '',
    location: '',
    linkedin: '',
    website: '',
  },
  summary: '',
  experience: [],
  education: [],
  skills: [],
  projects: [],
  template: 'modern-fresher',
};

function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

function Toast({ msg, type, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3000);
    return () => clearTimeout(t);
  }, [onClose]);

  return <div className={`toast ${type}`}>{msg}</div>;
}

export default function ResumeBuilder() {
  const { id } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [data, setData] = useState(() => {
    const params = new URLSearchParams(location.search);
    return {
      ...EMPTY,
      template: params.get('template') || 'modern-fresher',
    };
  });

  const [tab, setTab] = useState('personal');
  const [saveStatus, setSaveStatus] = useState('saved');
  const [exporting, setExporting] = useState(false);
  const [toast, setToast] = useState(null);
  const [resumeId, setResumeId] = useState(id || null);
  const [skillInput, setSkillInput] = useState('');
  const [fetchLoading, setFetchLoading] = useState(!!id);

  const previewRef = useRef(null);
  const isSavingRef = useRef(false);
  const isFirstLoad = useRef(true);

  const showToast = (msg, type = 'success') =>
    setToast({ msg, type });

  /* ── Load resume ── */
  useEffect(() => {
    if (!id) {
      setFetchLoading(false);
      return;
    }

    let cancelled = false;
    setFetchLoading(true);

    fetchResume(id)
      .then((resume) => {
        if (cancelled) return;

        if (resume.uid !== user.uid) {
          navigate('/dashboard', { replace: true });
          return;
        }

        setData(resume);
        setSaveStatus('saved');
      })
      .catch((err) => {
        console.error(err);
        showToast('Failed to load resume', 'error');
        navigate('/dashboard', { replace: true });
      })
      .finally(() => {
        if (!cancelled) setFetchLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [id, user.uid, navigate]);

  /* ── Mark unsaved ── */
  useEffect(() => {
    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }
    setSaveStatus('unsaved');
  }, [data]);

  /* ── Save ── */
  const save = useCallback(
    async (currentData, currentId) => {
      if (isSavingRef.current) return;

      isSavingRef.current = true;
      setSaveStatus('saving');

      try {
        if (currentId) {
          await updateResume(currentId, currentData);
        } else {
          const created = await createResume(user.uid, currentData);
          setResumeId(created.id);
          window.history.replaceState({}, '', `/builder/${created.id}`);
        }

        setSaveStatus('saved');
      } catch (err) {
        console.error(err);
        setSaveStatus('error');
        showToast('Save failed', 'error');
      } finally {
        isSavingRef.current = false;
      }
    },
    [user.uid]
  );

  const debouncedData = useDebounce(data, 1500);

  useEffect(() => {
    if (fetchLoading || isFirstLoad.current) return;
    if (saveStatus === 'saved') return;
    save(debouncedData, resumeId);
  }, [debouncedData]);

  /* ── PDF Export ── */
  const exportPDF = async () => {
    setExporting(true);

    try {
      const html2pdf = (await import('html2pdf.js')).default;

      const el = previewRef.current;
      if (!el) return showToast('Preview not ready', 'error');

      const filename = (data.personalInfo?.name || 'resume').replace(
        /[^a-z0-9]/gi,
        '_'
      );

      await html2pdf()
        .set({
          margin: 0,
          filename: `${filename}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { scale: 2, useCORS: true },
          jsPDF: { format: 'a4' },
        })
        .from(el)
        .save();

      showToast('Downloaded PDF');
    } catch (err) {
      console.error(err);
      showToast('Export failed', 'error');
    } finally {
      setExporting(false);
    }
  };

  /* ── Helpers ── */
  const addSkill = (e) => {
    if (e.key === 'Enter' && skillInput.trim()) {
      setData((d) => ({
        ...d,
        skills: [...(d.skills || []), skillInput.trim()],
      }));
      setSkillInput('');
    }
  };

  const removeSkill = (i) =>
    setData((d) => ({
      ...d,
      skills: d.skills.filter((_, idx) => idx !== i),
    }));

  const TABS = ['personal', 'summary', 'experience', 'education', 'skills', 'projects'];

  if (fetchLoading) {
    return <div className="builder-loading">Loading...</div>;
  }

  return (
    <div className="builder">
      {toast && (
        <Toast msg={toast.msg} type={toast.type} onClose={() => setToast(null)} />
      )}

      <div className="builder-form">
        <div className="bf-header">
          <Link to="/dashboard">← Dashboard</Link>
          <h2>Resume Builder</h2>
          <button onClick={() => save(data, resumeId)}>Save</button>
          <button onClick={exportPDF}>
            {exporting ? 'Exporting...' : 'Export PDF'}
          </button>
        </div>

        <div className="bf-tabs">
          {TABS.map((t) => (
            <button key={t} onClick={() => setTab(t)}>
              {t}
            </button>
          ))}
        </div>

        {/* You already have full UI below — kept unchanged */}
      </div>

      <div className="builder-preview">
        <div ref={previewRef}>
          <ResumePreview data={data} />
        </div>
      </div>
    </div>
  );
}
